1	package com.example.starter.hazmat.service;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.LocalDateTime;
7	import java.util.ArrayList;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Optional;
12	
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.PlatformTransactionManager;
16	import org.springframework.transaction.support.TransactionTemplate;
17	
18	import com.example.starter.hazmat.api.ApiException;
19	import com.example.starter.hazmat.clock.MutableClock;
20	import com.example.starter.hazmat.domain.RouteApprovalStatus;
21	import com.example.starter.hazmat.domain.ShipmentStatus;
22	import com.example.starter.hazmat.domain.WaypointState;
23	import com.example.starter.hazmat.dto.ApplyRequest;
24	import com.example.starter.hazmat.dto.CheckinRequest;
25	import com.example.starter.hazmat.dto.RerouteRequest;
26	import com.example.starter.hazmat.po.ApprovalWaypoint;
27	import com.example.starter.hazmat.po.Checkin;
28	import com.example.starter.hazmat.po.GoodsCategory;
29	import com.example.starter.hazmat.po.IdempotentRecord;
30	import com.example.starter.hazmat.po.RouteApproval;
31	import com.example.starter.hazmat.po.RouteInfo;
32	import com.example.starter.hazmat.po.RouteWaypointDef;
33	import com.example.starter.hazmat.po.Shipment;
34	import com.example.starter.hazmat.po.ShipmentEvent;
35	import com.example.starter.hazmat.repo.HazmatRepository;
36	import com.fasterxml.jackson.core.JsonProcessingException;
37	import com.fasterxml.jackson.databind.ObjectMapper;
38	
39	/**
40	 * 危化品运输路线管制与押运打卡核心服务。
41	 *
42	 * <p>事务边界：写操作通过 {@link TransactionTemplate} 显式包裹；幂等占位独立于业务事务提交，
43	 * 业务失败（含逆序打卡拒绝）也记录首次结果用于同键重放；逆序告警使用独立事务保证回滚不丢告警。
44	 */
45	@Service
46	public class HazmatService {
47	
48	    /** 事件类型。 */
49	    public static final String EVT_ROUTE_REJECTED = "ROUTE_REJECTED";
50	    public static final String EVT_REROUTE_REJECTED = "REROUTE_REJECTED";
51	    public static final String EVT_REROUTE_SWITCH = "REROUTE_SWITCH";
52	    public static final String EVT_CHECKIN_REVERSED = "CHECKIN_REVERSED";
53	    public static final String EVT_DEVIATION_WARNING = "DEVIATION_WARNING";
54	    public static final String EVT_LOST_CONTACT = "LOST_CONTACT";
55	    public static final String EVT_LATE_CHECKIN_AFTER_CLOSE = "LATE_CHECKIN_AFTER_CLOSE";
56	
57	    /** 连续超时途经点数达到该值即升级失联（恰 2 个触发）。 */
58	    static final int LOST_CONTACT_CONSECUTIVE_TIMEOUTS = 2;
59	
60	    private final HazmatRepository repository;
61	    private final EventRecorder eventRecorder;
62	    private final MutableClock clock;
63	    private final TransactionTemplate tx;
64	    private final ObjectMapper objectMapper;
65	
66	    public HazmatService(HazmatRepository repository, EventRecorder eventRecorder,
67	                         MutableClock clock, PlatformTransactionManager transactionManager,
68	                         ObjectMapper objectMapper) {
69	        this.repository = repository;
70	        this.eventRecorder = eventRecorder;
71	        this.clock = clock;
72	        this.tx = new TransactionTemplate(transactionManager);
73	        this.objectMapper = objectMapper;
74	    }
75	
76	    private LocalDateTime now() {
77	        return clock.now();
78	    }
79	
80	    // ============================ 运输申请 ============================
81	
82	    public ServiceResult apply(ApplyRequest request) {
83	        String fingerprint = fingerprint("APPLY",
84	                request.requestId(), request.vehiclePlate(), request.goodsCategory(),
85	                request.routeCode(), request.plannedDeparture().toString());
86	        return withIdempotency(request.requestId(), fingerprint,
87	                () -> tx.execute(status -> doApply(request)));
88	    }
89	
90	    private ServiceResult doApply(ApplyRequest request) {
91	        LocalDateTime now = now();
92	        GoodsCategory category = repository.findCategory(request.goodsCategory())
93	                .orElseThrow(() -> ApiException.badRequest("CATEGORY_NOT_FOUND",
94	                        "危化品类别不存在: " + request.goodsCategory()));
95	        RouteInfo route = repository.findRoute(request.routeCode())
96	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
97	                        "路线不存在: " + request.routeCode()));
98	        var vehicle = repository.findVehicle(request.vehiclePlate())
99	                .orElseThrow(() -> ApiException.badRequest("VEHICLE_NOT_FOUND",
100	                        "车辆不存在: " + request.vehiclePlate()));
101	        if (vehicle.frozen()) {
102	            throw ApiException.conflict("VEHICLE_FROZEN",
103	                    "车辆 " + request.vehiclePlate() + " 已因失联冻结，禁止新申请");
104	        }
105	        if (repository.findActiveShipment(request.vehiclePlate()).isPresent()) {
106	            throw ApiException.conflict("VEHICLE_BUSY",
107	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
108	        }
109	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
110	        if (defs.isEmpty()) {
111	            throw ApiException.badRequest("ROUTE_WAYPOINTS_MISSING",
112	                    "路线 " + request.routeCode() + " 未定义途经点");
113	        }
114	
115	        String shipmentNo = "HZ" + request.plannedDeparture().toLocalDate().toString().replace("-", "")
116	                + "-" + Integer.toHexString(request.requestId().hashCode() & 0x7fffffff).toUpperCase();
117	        long shipmentId = repository.insertShipment(shipmentNo, request.vehiclePlate(),
118	                request.goodsCategory(), ShipmentStatus.APPLIED, null,
119	                request.plannedDeparture(), now);
120	        try {
121	            // 主键冲突即并发占用失败：回滚运单，返回 409。
122	            repository.occupyVehicle(request.vehiclePlate(), shipmentId);
123	        } catch (DuplicateKeyException e) {
124	            throw ApiException.conflict("VEHICLE_BUSY",
125	                    "车辆 " + request.vehiclePlate() + " 同时刻只允许一个执行中运单");
126	        }
127	        long approvalId = repository.insertApproval(shipmentId, request.routeCode(), 1,
128	                RouteApprovalStatus.PENDING, null, now);
129	        for (RouteWaypointDef def : defs) {
130	            repository.insertWaypoint(approvalId, shipmentId, def.seq(), def.name(),
131	                    request.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
132	        }
133	        repository.updateCurrentApproval(shipmentId, approvalId);
134	
135	        Map<String, Object> body = baseShipmentView(repository.findShipmentById(shipmentId).orElseThrow());
136	        body.put("message", "申请已受理，等待路线核准");
137	        return ServiceResult.ok(body);
138	    }
139	
140	    // ============================ 路线核准 ============================
141	
142	    public ServiceResult decideApproval(String shipmentNo, boolean approved) {
143	        return tx.execute(status -> doDecide(shipmentNo, approved));
144	    }
145	
146	    private ServiceResult doDecide(String shipmentNo, boolean approved) {
147	        Shipment shipment = loadShipment(shipmentNo);
148	        if (shipment.status() != ShipmentStatus.APPLIED) {
149	            throw ApiException.conflict("INVALID_STATUS",
150	                    "运单当前状态 " + shipment.status() + "，不可路线核准");
151	        }
152	        RouteApproval approval = currentApproval(shipment);
153	        if (approval.status() != RouteApprovalStatus.PENDING || approval.versionNo() != 1) {
154	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "首版路线核准记录状态异常");
155	        }
156	        LocalDateTime now = now();
157	
158	        RouteRuleEvaluator.Result result = evaluate(approval.routeCode(),
159	                shipment.goodsCategory(), shipment.plannedDeparture());
160	        if (!approved || !result.allowed()) {
161	            // 驳回事务必须落库（终态 + 释放车辆占用），故提交后返回 422，而非抛异常回滚。
162	            String reason = approved ? result.message() : "人工驳回";
163	            repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.REJECTED, now);
164	            repository.insertEvent(shipment.id(), EVT_ROUTE_REJECTED, reason, now);
165	            repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_REJECTED);
166	            repository.releaseVehicle(shipment.vehiclePlate());
167	            Map<String, Object> body = shipmentView(shipmentNo);
168	            body.put("errorCode", "ROUTE_REJECTED");
169	            body.put("message", reason);
170	            return ServiceResult.status(422, body);
171	        }
172	        repository.updateApprovalStatus(approval.id(), RouteApprovalStatus.APPROVED, now);
173	        repository.updateStatus(shipment.id(), ShipmentStatus.ROUTE_APPROVED);
174	        return ServiceResult.ok(shipmentView(shipmentNo));
175	    }
176	
177	    // ============================ 发运 ============================
178	
179	    public ServiceResult dispatch(String shipmentNo, String requestId) {
180	        String fingerprint = fingerprint("DISPATCH", requestId, shipmentNo);
181	        return withIdempotency(requestId, fingerprint,
182	                () -> tx.execute(status -> doDispatch(shipmentNo)));
183	    }
184	
185	    private ServiceResult doDispatch(String shipmentNo) {
186	        Shipment shipment = loadShipment(shipmentNo);
187	        if (shipment.status() == ShipmentStatus.DISPATCHED || shipment.status() == ShipmentStatus.IN_TRANSIT) {
188	            throw ApiException.conflict("ALREADY_DISPATCHED", "运单已发运");
189	        }
190	        if (shipment.status() != ShipmentStatus.ROUTE_APPROVED) {
191	            throw ApiException.conflict("INVALID_STATUS",
192	                    "运单当前状态 " + shipment.status() + "，不可发运");
193	        }
194	        repository.updateStatus(shipment.id(), ShipmentStatus.DISPATCHED);
195	        return ServiceResult.ok(shipmentView(shipmentNo));
196	    }
197	
198	    // ============================ 押运打卡 ============================
199	
200	    public ServiceResult checkin(String shipmentNo, CheckinRequest request) {
201	        String fingerprint = fingerprint("CHECKIN", request.requestId(), shipmentNo,
202	                String.valueOf(request.waypointSeq()), request.checkTime().toString());
203	        // 逆序拒绝走异常路径：告警独立事务落库，业务事务回滚，首次失败响应同样幂等保存。
204	        return withIdempotency(request.requestId(), fingerprint,
205	                () -> tx.execute(status -> doCheckin(shipmentNo, request)));
206	    }
207	
208	    private ServiceResult doCheckin(String shipmentNo, CheckinRequest request) {
209	        Shipment shipment = loadShipment(shipmentNo);
210	        LocalDateTime now = now();
211	
212	        if (shipment.status() == ShipmentStatus.COMPLETED) {
213	            // 结案为终态：迟到打卡不改任何业务状态，只记录迟到事件。
214	            eventRecorder.recordNewTransaction(shipment.id(), EVT_LATE_CHECKIN_AFTER_CLOSE,
215	                    "结案后收到途经点 " + request.waypointSeq() + " 打卡，时刻 " + request.checkTime(), now);
216	            Map<String, Object> body = shipmentView(shipmentNo);
217	            body.put("lateAfterClosed", true);
218	            return ServiceResult.ok(body);
219	        }
220	        if (shipment.status().isTerminal()) {
221	            throw ApiException.conflict("SHIPMENT_TERMINAL",
222	                    "运单终态 " + shipment.status() + "，不可打卡");
223	        }
224	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
225	            throw ApiException.conflict("NOT_DISPATCHED",
226	                    "运单当前状态 " + shipment.status() + "，不可打卡");
227	        }
228	
229	        long approvalId = shipment.currentApprovalId();
230	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
231	        ApprovalWaypoint target = waypoints.stream()
232	                .filter(w -> w.seq() == request.waypointSeq()).findFirst()
233	                .orElseThrow(() -> ApiException.badRequest("WAYPOINT_NOT_FOUND",
234	                        "当前路线无途经点序号 " + request.waypointSeq()));
235	
236	        Optional<Checkin> duplicate = repository.findCheckin(shipment.id(), approvalId, target.seq());
237	        if (duplicate.isPresent()) {
238	            throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
239	                    "途经点 " + target.seq() + " 已打卡（运单+途经点序号去重），首次打卡时刻 "
240	                            + duplicate.get().checkTime());
241	        }
242	
243	        // 时序校验：与最近的前序、后序已打卡途经点比较；乱序回传允许（按时刻归位），时刻逆序拒绝并告警。
244	        Checkin prev = nearestChecked(waypoints, target.seq(), true);
245	        Checkin next = nearestChecked(waypoints, target.seq(), false);
246	        if (prev != null && !request.checkTime().isAfter(prev.checkTime())) {
247	            rejectReverse(shipment, target.seq(), request.checkTime(),
248	                    "晚于前序途经点 " + prev.seq() + " 的打卡时刻 " + prev.checkTime(), now);
249	        }
250	        if (next != null && !request.checkTime().isBefore(next.checkTime())) {
251	            rejectReverse(shipment, target.seq(), request.checkTime(),
252	                    "早于后序途经点 " + next.seq() + " 的打卡时刻 " + next.checkTime(), now);
253	        }
254	
255	        boolean late = !request.checkTime().isBefore(target.deadline());
256	        WaypointState targetState = late ? WaypointState.CHECKED_LATE : WaypointState.CHECKED;
257	        int rows;
258	        if (late) {
259	            // 既可能从未扫描（PENDING），也可能已被标记偏离（TIMED_OUT）。
260	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
261	                    WaypointState.PENDING, targetState, request.checkTime())
262	                    + repository.compareAndSetWaypointState(approvalId, target.seq(),
263	                    WaypointState.TIMED_OUT, targetState, request.checkTime());
264	        } else {
265	            rows = repository.compareAndSetWaypointState(approvalId, target.seq(),
266	                    WaypointState.PENDING, targetState, request.checkTime());
267	        }
268	        if (rows == 0) {
269	            // 并发：监控扫描或另一打卡刚刚改变状态。
270	            Optional<Checkin> raced = repository.findCheckin(shipment.id(), approvalId, target.seq());
271	            if (raced.isPresent()) {
272	                throw ApiException.conflict("WAYPOINT_ALREADY_CHECKED",
273	                        "途经点 " + target.seq() + " 已打卡，首次打卡时刻 " + raced.get().checkTime());
274	            }
275	            throw ApiException.conflict("WAYPOINT_STATE_CHANGED",
276	                    "途经点 " + target.seq() + " 状态刚被更新，请重试");
277	        }
278	        repository.insertCheckin(shipment.id(), approvalId, target.seq(),
279	                request.checkTime(), request.requestId(), now);
280	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
281	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
282	        }
283	        return ServiceResult.ok(shipmentView(shipmentNo));
284	    }
285	
286	    private void rejectReverse(Shipment shipment, int seq, LocalDateTime checkTime, String detail, LocalDateTime now) {
287	        String message = "途经点 " + seq + " 打卡时刻 " + checkTime + " 未" + detail + "，逆序拒绝";
288	        eventRecorder.recordNewTransaction(shipment.id(), EVT_CHECKIN_REVERSED, message, now);
289	        throw ApiException.badRequest("CHECKIN_REVERSED", message);
290	    }
291	
292	    /** 查找序号最近的已打卡途经点：backward=true 向前，false 向后（仅限当前生效路线版本）。 */
293	    private Checkin nearestChecked(List<ApprovalWaypoint> waypoints, int seq, boolean backward) {
294	        ApprovalWaypoint result = null;
295	        for (ApprovalWaypoint w : waypoints) {
296	            if (backward ? (w.seq() < seq) : (w.seq() > seq)) {
297	                if (result == null
298	                        || (backward && w.seq() > result.seq())
299	                        || (!backward && w.seq() < result.seq())) {
300	                    result = w;
301	                }
302	            }
303	        }
304	        if (result == null) {
305	            return null;
306	        }
307	        return repository.findCheckin(result.shipmentId(), result.approvalId(), result.seq()).orElse(null);
308	    }
309	
310	    // ============================ 紧急改线 ============================
311	
312	    public ServiceResult reroute(String shipmentNo, RerouteRequest request) {
313	        String fingerprint = fingerprint("REROUTE", request.requestId(), shipmentNo, request.routeCode());
314	        return withIdempotency(request.requestId(), fingerprint,
315	                () -> tx.execute(status -> doReroute(shipmentNo, request)));
316	    }
317	
318	    private ServiceResult doReroute(String shipmentNo, RerouteRequest request) {
319	        Shipment shipment = loadShipment(shipmentNo);
320	        if (shipment.status().isTerminal()) {
321	            throw ApiException.conflict("SHIPMENT_TERMINAL", "运单已终态，不可改线");
322	        }
323	        if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
324	            throw ApiException.conflict("INVALID_STATUS", "仅发运后可紧急改线，当前 " + shipment.status());
325	        }
326	        repository.findRoute(request.routeCode())
327	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND",
328	                        "路线不存在: " + request.routeCode()));
329	        List<RouteApproval> approvals = repository.findApprovals(shipment.id());
330	        boolean pendingExists = approvals.stream()
331	                .anyMatch(a -> a.status() == RouteApprovalStatus.PENDING);
332	        if (pendingExists) {
333	            throw ApiException.conflict("REROUTE_PENDING", "已有待核准改线申请，请先完成核准");
334	        }
335	        int nextVersion = approvals.stream().mapToInt(RouteApproval::versionNo).max().orElse(0) + 1;
336	        LocalDateTime now = now();
337	        long newApprovalId = repository.insertApproval(shipment.id(), request.routeCode(), nextVersion,
338	                RouteApprovalStatus.PENDING, null, now);
339	        List<RouteWaypointDef> defs = repository.findWaypointDefs(request.routeCode());
340	        for (RouteWaypointDef def : defs) {
341	            repository.insertWaypoint(newApprovalId, shipment.id(), def.seq(), def.name(),
342	                    shipment.plannedDeparture().plusMinutes(def.offsetMinutes()), WaypointState.PENDING);
343	        }
344	        Map<String, Object> body = shipmentView(shipmentNo);
345	        body.put("pendingApprovalId", newApprovalId);
346	        body.put("message", "改线申请已提交，核准通过前原路线打卡继续有效");
347	        return ServiceResult.ok(body);
348	    }
349	
350	    public ServiceResult approveReroute(String shipmentNo, long approvalId) {
351	        return tx.execute(status -> doApproveReroute(shipmentNo, approvalId));
352	    }
353	
354	    private ServiceResult doApproveReroute(String shipmentNo, long approvalId) {
355	        Shipment shipment = loadShipment(shipmentNo);
356	        RouteApproval next = repository.findApproval(approvalId)
357	                .orElseThrow(() -> ApiException.notFound("APPROVAL_NOT_FOUND", "核准记录不存在"));
358	        if (next.shipmentId() != shipment.id()) {
359	            throw ApiException.badRequest("APPROVAL_MISMATCH", "核准记录不属于该运单");
360	        }
361	        if (next.status() != RouteApprovalStatus.PENDING || next.versionNo() <= 1) {
362	            throw ApiException.conflict("APPROVAL_NOT_PENDING", "该记录不是待核准改线申请");
363	        }
364	        LocalDateTime now = now();
365	        RouteRuleEvaluator.Result result = evaluate(next.routeCode(),
366	                shipment.goodsCategory(), shipment.plannedDeparture());
367	        if (!result.allowed()) {
368	            // 改线驳回仅落库新记录的驳回结果，原路线继续有效；提交后返回 422。
369	            repository.updateApprovalStatus(next.id(), RouteApprovalStatus.REJECTED, now);
370	            repository.insertEvent(shipment.id(), EVT_REROUTE_REJECTED, result.message(), now);
371	            Map<String, Object> body = shipmentView(shipmentNo);
372	            body.put("errorCode", "REROUTE_REJECTED");
373	            body.put("message", result.message());
374	            return ServiceResult.status(422, body);
375	        }
376	        // 同一事务：旧路线终止 + 新路线生效 + 运单指向切换。
377	        RouteApproval old = currentApproval(shipment);
378	        repository.updateApprovalStatus(old.id(), RouteApprovalStatus.TERMINATED, now);
379	        repository.updateApprovalStatus(next.id(), RouteApprovalStatus.APPROVED, now);
380	        repository.updateCurrentApproval(shipment.id(), next.id());
381	        if (shipment.status() == ShipmentStatus.DISPATCHED) {
382	            repository.updateStatus(shipment.id(), ShipmentStatus.IN_TRANSIT);
383	        }
384	        repository.insertEvent(shipment.id(), EVT_REROUTE_SWITCH,
385	                "路线由 " + old.routeCode() + "(v" + old.versionNo() + ") 切换为 "
386	                        + next.routeCode() + "(v" + next.versionNo() + ")，原路线打卡保留", now);
387	        return ServiceResult.ok(shipmentView(shipmentNo));
388	    }
389	
390	    // ============================ 到达核销 ============================
391	
392	    public ServiceResult complete(String shipmentNo, String requestId) {
393	        String fingerprint = fingerprint("COMPLETE", requestId, shipmentNo);
394	        return withIdempotency(requestId, fingerprint,
395	                () -> tx.execute(status -> doComplete(shipmentNo)));
396	    }
397	
398	    private ServiceResult doComplete(String shipmentNo) {
399	        Shipment shipment = loadShipment(shipmentNo);
400	        if (shipment.status() == ShipmentStatus.COMPLETED) {
401	            // 结案终态：重复核销（无论是否同 requestId）返回幂等成功。
402	            return ServiceResult.ok(shipmentView(shipmentNo));
403	        }
404	        if (shipment.status() == ShipmentStatus.LOST_CONTACT) {
405	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
406	        }
407	        // 条件更新：与失联升级竞争，败者拿不到终态。
408	        int rows = repository.compareAndSetTerminal(shipment.id(), ShipmentStatus.COMPLETED);
409	        if (rows == 0) {
410	            Shipment current = repository.findShipmentById(shipment.id()).orElseThrow();
411	            if (current.status() == ShipmentStatus.COMPLETED) {
412	                return ServiceResult.ok(shipmentView(shipmentNo));
413	            }
414	            throw ApiException.conflict("ALREADY_LOST_CONTACT", "运单已失联冻结，不可核销");
415	        }
416	        repository.releaseVehicle(shipment.vehiclePlate());
417	        return ServiceResult.ok(shipmentView(shipmentNo));
418	    }
419	
420	    // ============================ 超时/失联监控（可复算） ============================
421	
422	    public ServiceResult scanTimeouts(LocalDateTime at) {
423	        LocalDateTime now = at != null ? at : now();
424	        List<Map<String, Object>> affected = new ArrayList<>();
425	        List<Shipment> actives;
426	        try {
427	            actives = tx.execute(status -> repository.findActiveShipments());
428	        } catch (Exception e) {
429	            throw ApiException.badRequest("SCAN_FAILED", e.getMessage());
430	        }
431	        for (Shipment shipment : actives) {
432	            if (shipment.status() != ShipmentStatus.DISPATCHED && shipment.status() != ShipmentStatus.IN_TRANSIT) {
433	                continue;
434	            }
435	            try {
436	                Map<String, Object> changed = tx.execute(status -> scanOne(shipment.id(), now));
437	                if (changed != null && Boolean.TRUE.equals(changed.get("changed"))) {
438	                    affected.add(changed);
439	                }
440	            } catch (ApiException e) {
441	                throw e;
442	            } catch (Exception ignored) {
443	                // 单个运单扫描失败不影响其他运单（终态竞争败者等）。
444	            }
445	        }
446	        return ServiceResult.ok(Map.of("scanAt", now.toString(), "affected", affected));
447	    }
448	
449	    /** 扫描单个运单：标记超时点；连续 2 点超时则升级失联并冻结（唯一终态 CAS）。 */
450	    private Map<String, Object> scanOne(long shipmentId, LocalDateTime now) {
451	        Shipment shipment = repository.findShipmentById(shipmentId).orElseThrow();
452	        if (shipment.status().isTerminal()) {
453	            return Map.of();
454	        }
455	        long approvalId = shipment.currentApprovalId();
456	        List<ApprovalWaypoint> waypoints = repository.findWaypoints(approvalId);
457	        List<Integer> timedOut = new ArrayList<>();
458	        for (ApprovalWaypoint w : waypoints) {
459	            if (w.state() == WaypointState.PENDING && !now.isBefore(w.deadline())) {
460	                int rows = repository.compareAndSetWaypointState(approvalId, w.seq(),
461	                        WaypointState.PENDING, WaypointState.TIMED_OUT, null);
462	                if (rows == 1) {
463	                    timedOut.add(w.seq());
464	                    repository.insertEvent(shipmentId, EVT_DEVIATION_WARNING,
465	                            "途经点 " + w.seq() + "(" + w.name() + ") 计划通过时刻 " + w.plannedTime()
466	                                    + "，超时阈值 " + w.deadline() + "，扫描时刻 " + now + " 仍未打卡", now);
467	                }
468	            }
469	        }
470	        boolean lost = hasConsecutiveTimeouts(repository.findWaypoints(approvalId));
471	        boolean upgraded = false;
472	        if (lost) {
473	            int rows = repository.compareAndSetTerminal(shipmentId, ShipmentStatus.LOST_CONTACT);
474	            if (rows == 1) {
475	                upgraded = true;
476	                repository.freezeVehicle(shipment.vehiclePlate(), shipmentId, now);
477	                repository.releaseVehicle(shipment.vehiclePlate());
478	                repository.insertEvent(shipmentId, EVT_LOST_CONTACT,
479	                        "连续 2 个途经点超时未打卡，升级失联并冻结车辆 " + shipment.vehiclePlate(), now);
480	            }
481	        }
482	        if (timedOut.isEmpty() && !upgraded) {
483	            return Map.of();
484	        }
485	        Map<String, Object> changed = new LinkedHashMap<>();
486	        changed.put("changed", true);
487	        changed.put("shipmentNo", shipment.shipmentNo());
488	        changed.put("newlyTimedOut", timedOut);
489	        changed.put("lostContact", upgraded);
490	        return changed;
491	    }
492	
493	    /** 连续超时判定：按序号相邻的两个途经点均处于 TIMED_OUT（恰 2 个即触发）。 */
494	    static boolean hasConsecutiveTimeouts(List<ApprovalWaypoint> waypoints) {
495	        List<ApprovalWaypoint> sorted = waypoints.stream()
496	                .sorted(java.util.Comparator.comparingInt(ApprovalWaypoint::seq)).toList();
497	        int consecutive = 0;
498	        for (ApprovalWaypoint w : sorted) {
499	            if (w.state() == WaypointState.TIMED_OUT) {
500	                consecutive++;
501	                if (consecutive >= LOST_CONTACT_CONSECUTIVE_TIMEOUTS) {
502	                    return true;
503	                }
504	            } else {
505	                consecutive = 0;
506	            }
507	        }
508	        return false;
509	    }
510	
511	    // ============================ 查询视图 ============================
512	
513	    public ServiceResult getShipment(String shipmentNo) {
514	        return ServiceResult.ok(shipmentView(shipmentNo));
515	    }
516	
517	    private Shipment loadShipment(String shipmentNo) {
518	        return repository.findShipmentByNo(shipmentNo)
519	                .orElseThrow(() -> ApiException.notFound("SHIPMENT_NOT_FOUND", "运单不存在: " + shipmentNo));
520	    }
521	
522	    private RouteApproval currentApproval(Shipment shipment) {
523	        return repository.findApproval(shipment.currentApprovalId())
524	                .orElseThrow(() -> ApiException.badRequest("APPROVAL_NOT_FOUND", "当前生效路线核准记录缺失"));
525	    }
526	
527	    private RouteRuleEvaluator.Result evaluate(String routeCode, String categoryCode, LocalDateTime departure) {
528	        GoodsCategory category = repository.findCategory(categoryCode)
529	                .orElseThrow(() -> ApiException.badRequest("CATEGORY_NOT_FOUND", "危化品类别不存在"));
530	        RouteInfo route = repository.findRoute(routeCode)
531	                .orElseThrow(() -> ApiException.badRequest("ROUTE_NOT_FOUND", "路线不存在"));
532	        return RouteRuleEvaluator.evaluate(route, category.requiredLevel(), departure,
533	                repository.findWaypointDefs(routeCode), repository.findControlPeriods(routeCode));
534	    }
535	
536	    private Map<String, Object> baseShipmentView(Shipment shipment) {
537	        Map<String, Object> body = new LinkedHashMap<>();
538	        body.put("shipmentNo", shipment.shipmentNo());
539	        body.put("vehiclePlate", shipment.vehiclePlate());
540	        body.put("goodsCategory", shipment.goodsCategory());
541	        body.put("status", shipment.status().name());
542	        body.put("terminal", shipment.status().isTerminal());
543	        body.put("plannedDeparture", shipment.plannedDeparture().toString());
544	        return body;
545	    }
546	
547	    private Map<String, Object> shipmentView(String shipmentNo) {
548	        Shipment shipment = loadShipment(shipmentNo);
549	        Map<String, Object> body = baseShipmentView(shipment);
550	        repository.findVehicle(shipment.vehiclePlate()).ifPresent(v -> body.put("vehicleFrozen", v.frozen()));
551	
552	        List<Map<String, Object>> approvalViews = new ArrayList<>();
553	        for (RouteApproval approval : repository.findApprovals(shipment.id())) {
554	            Map<String, Object> av = new LinkedHashMap<>();
555	            av.put("approvalId", approval.id());
556	            av.put("versionNo", approval.versionNo());
557	            av.put("routeCode", approval.routeCode());
558	            av.put("status", approval.status().name());
559	            av.put("rejectReason", approval.rejectReason());
560	            av.put("current", approval.id() == shipment.currentApprovalId());
561	
562	            List<Checkin> checkins = repository.findCheckinsByApproval(approval.id());
563	            List<Map<String, Object>> wpViews = new ArrayList<>();
564	            for (ApprovalWaypoint w : repository.findWaypoints(approval.id())) {
565	                Map<String, Object> wv = new LinkedHashMap<>();
566	                wv.put("seq", w.seq());
567	                wv.put("name", w.name());
568	                wv.put("plannedTime", w.plannedTime().toString());
569	                wv.put("deadline", w.deadline().toString());
570	                wv.put("state", w.state().name());
571	                wv.put("checkedTime", w.checkedTime() == null ? null : w.checkedTime().toString());
572	                checkins.stream().filter(c -> c.seq() == w.seq()).findFirst()
573	                        .ifPresent(c -> wv.put("requestId", c.requestId()));
574	                wpViews.add(wv);
575	            }
576	            av.put("waypoints", wpViews);
577	            approvalViews.add(av);
578	        }
579	        body.put("approvals", approvalViews);
580	
581	        List<Map<String, Object>> eventViews = new ArrayList<>();
582	        for (ShipmentEvent e : repository.findEvents(shipment.id())) {
583	            Map<String, Object> ev = new LinkedHashMap<>();
584	            ev.put("eventType", e.eventType());
585	            ev.put("detail", e.detail());
586	            ev.put("eventTime", e.eventTime().toString());
587	            eventViews.add(ev);
588	        }
589	        body.put("events", eventViews);
590	        return body;
591	    }
592	
593	    // ============================ 幂等支撑 ============================
594	
595	    /**
596	     * 以 requestId 幂等执行业务动作：
597	     * <ul>
598	     *   <li>同键同参：返回首次结果（成功或业务失败，含首次 HTTP 状态码）；</li>
599	     *   <li>同键异参：指纹不符返回 409；</li>
600	     *   <li>处理中并发：返回 409。</li>
601	     * </ul>
602	     */
603	    private ServiceResult withIdempotency(String requestId, String fingerprint,
604	                                          java.util.function.Supplier<ServiceResult> action) {
605	        for (int attempt = 0; attempt < 2; attempt++) {
606	            Optional<IdempotentRecord> existing = repository.findIdempotent(requestId);
607	            if (existing.isPresent()) {
608	                IdempotentRecord record = existing.get();
609	                if (!record.fingerprint().equals(fingerprint)) {
610	                    throw ApiException.conflict("IDEMPOTENT_FINGERPRINT_MISMATCH",
611	                            "requestId=" + requestId + " 已用于不同业务参数");
612	                }
613	                if ("COMPLETED".equals(record.status())) {
614	                    Map<String, Object> stored = parseJson(record.responseBody());
615	                    // 非 2xx 首次结果以相同状态码/错误码重放，保持 HTTP 语义一致。
616	                    if (record.httpStatus() != null && record.httpStatus() >= 400) {
617	                        Object code = stored.get("errorCode");
618	                        if (code == null) {
619	                            code = stored.get("code");
620	                        }
621	                        throw new ApiException(org.springframework.http.HttpStatus.valueOf(record.httpStatus()),
622	                                code == null ? "IDEMPOTENT_REPLAY" : code.toString(),
623	                                stored.get("message") == null ? "" : stored.get("message").toString());
624	                    }
625	                    return new ServiceResult(record.httpStatus(), stored);
626	                }
627	                throw ApiException.conflict("IDEMPOTENT_PROCESSING",
628	                        "相同 requestId 请求正在处理中");
629	            }
630	            boolean inserted = repository.insertProcessingIdempotent(requestId, fingerprint, now());
631	            if (!inserted) {
632	                continue; // 并发插入竞争：重读记录走重放分支
633	            }
634	            try {
635	                ServiceResult result = action.get();
636	                repository.completeIdempotent(requestId, result.httpStatus(), toJson(result.body()));
637	                return result;
638	            } catch (ApiException e) {
639	                Map<String, Object> errorBody = Map.of(
640	                        "code", e.getCode(),
641	                        "message", e.getMessage() == null ? "" : e.getMessage());
642	                repository.completeIdempotent(requestId, e.getStatus().value(), toJson(errorBody));
643	                throw e;
644	            } catch (RuntimeException e) {
645	                // 系统异常：保留 PROCESSING 之外，直接抛出（占位不删除，便于排查）。
646	                throw e;
647	            }
648	        }
649	        throw ApiException.conflict("IDEMPOTENT_RACE", "幂等记录并发竞争，请稍后重试");
650	    }
651	
652	    @SuppressWarnings("unchecked")
653	    private Map<String, Object> parseJson(String json) {
654	        if (json == null || json.isBlank()) {
655	            return Map.of();
656	        }
657	        try {
658	            return objectMapper.readValue(json, Map.class);
659	        } catch (JsonProcessingException e) {
660	            return Map.of("raw", json);
661	        }
662	    }
663	
664	    private String toJson(Map<String, Object> body) {
665	        try {
666	            return objectMapper.writeValueAsString(body);
667	        } catch (JsonProcessingException e) {
668	            throw new IllegalStateException("响应序列化失败", e);
669	        }
670	    }
671	
672	    private static String fingerprint(String operation, Object... parts) {
673	        StringBuilder sb = new StringBuilder(operation);
674	        for (Object part : parts) {
675	            sb.append('|').append(part);
676	        }
677	        try {
678	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
679	            byte[] hash = digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
680	            StringBuilder hex = new StringBuilder();
681	            for (byte b : hash) {
682	                hex.append(String.format("%02x", b));
683	            }
684	            return hex.toString();
685	        } catch (NoSuchAlgorithmException e) {
686	            throw new IllegalStateException(e);
687	        }
688	    }
689	}
