8	/**
9	 * 可控时钟：测试中可显式设定"当前时刻"，便于复算超时边界；默认使用系统时钟（Asia/Shanghai）。
10	 */
11	public class MutableClock extends Clock {
12	
13	    /** 业务统一时区。 */
14	    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
15	
16	    private volatile Instant instant;
17	    private volatile ZoneId zone = ZONE;
18	
19	    public MutableClock() {
20	        this.instant = null;
21	    }
22	
23	    /** 设定当前时刻（仅用于测试/管理侧复算）。 */
24	    public void setTime(LocalDateTime time) {
25	        this.instant = time.atZone(zone).toInstant();
26	    }
27	
28	    /** 清除固定时刻，恢复跟随系统时钟。 */
29	    public void reset() {
30	        this.instant = null;
31	    }
32	
33	    public LocalDateTime now() {
34	        return LocalDateTime.now(this);
35	    }
36	
37	    @Override
38	    public ZoneId getZone() {
39	        return zone;
40	    }
41	
42	    @Override
43	    public Clock withZone(ZoneId zone) {
44	        MutableClock c = new MutableClock();
45	        c.instant = this.instant;
46	        c.zone = zone;
47	        return c;
48	    }
49	
50	    @Override
51	    public Instant instant() {
52	        return instant != null ? instant : Instant.now();
53	    }
54	}
