COMMENT ON TABLE shipment_active_relay IS '进行中接力段占用：创建接力段时插入，换班完成或禁行冻结时删除';

-- 接力段双人打卡：去重键 运单+途经点序号+押运员编号（同一押运员同一途经点仅一次）
CREATE TABLE IF NOT EXISTS relay_checkin (
    id           BIGINT AUTO_INCREMENT NOT NULL PRIMARY KEY,
