 */
private boolean freezeForCurfew(Shipment shipment, RelaySegment relay, LocalDateTime now) {
    int rows = repository.compareAndSetTerminal(shipment.id(), ShipmentStatus.CURFEW_FROZEN);
    if (rows == 0) {
